<div><pre tabindex="0"><code data-lang="c"><span><span><span>// Python/ceval.c
</span></span></span><span><span><span>//
</span></span></span><span><span><span>// Pushes `co_consts[consti]` onto the stack.
</span></span></span><span><span><span>//
</span></span></span><span><span><span>//
</span></span></span><span><span><span></span>PyObject* _Py_HOT_FUNCTION
</span></span><span><span>_PyEval_EvalFrameDefault(PyThreadState *tstate, PyFrameObject *f, <span>int</span> throwflag)
</span></span><span><span>{
</span></span><span><span>    _Py_EnsureTstateNotNULL(tstate);
</span></span><span><span>	...
</span></span><span><span>
</span></span><span><span>        <span>switch</span> (opcode) {
